   [39]={next_id=40, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="地面上，到处散落着破碎的机器零件和不知道属于谁的个人物品——它们大多沾染着血迹，和黑色的污染残痕。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_604.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [40]={next_id=41, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="墙壁上布满了深深浅浅的沟壑，那些沟壑有的整齐，如同刀砍，有的粗糙，像是被钝器反复敲击的痕迹。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_604.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [41]={next_id=42, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="沟壑下，是杂乱的拖拽痕迹，从这头延伸到那头，又从那头延伸回来，最后在某个角落里骤然停止。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_604.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
